import {CHALLENGE_CATEGORIES as categories,parseChallengeJSON,validateChallengeCatalog,validateChallengeReport,validateChallengeResponses,filterChallengeTasks,replayChallenge} from './challenge-data.js?v=20261101-short1';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>typeof x==='number'?x.toLocaleString('zh-CN',{maximumFractionDigits:2}):'—';
const labels={scored:'内容已评分',unscorable:'内容无法解析',pending:'待人工复核',blocked:'待隔离执行',not_applicable:'未评分'};
const diff={'candidate-medium':'候选进阶','candidate-hard':'候选挑战','candidate-frontier':'候选高难'};
const count=(title,value,note)=>`<div class="stat"><div class="stat-label">${e(title)}</div><div class="stat-value">${e(value)}</div><small>${e(note)}</small></div>`;
const pre=(s,label)=>`<pre class="evidence" aria-label="${e(label)}">${e(s)}</pre>`;
const link=(s,label)=>s?`<a class="source" target="_blank" rel="noopener noreferrer" href="${e(s)}">${e(label)} ↗</a>`:e(label);

export function challengeAssessment(a){
 return `<section class="challenge-assessment" aria-label="三层评分"><div class="challenge-score-grid"><div><small>内容完成度</small><strong>${a.contentScore===null?'—':n(a.contentScore)+' / 100'}</strong><span>${e(labels[a.contentState]||a.contentState)}</span></div><div><small>必要输出合同</small><strong>${a.contentState==='not_applicable'?'未检查':a.formatPassed?'满足':'未满足'}</strong><span>格式与约束单独核验</span></div><div><small>严格完成</small><strong>${a.strictPassed===null?'待定':a.strictPassed?'通过':'未通过'}</strong><span>核心内容与必要合同</span></div></div><p class="evidence-meta">${e(a.reason||({pending:'人工量表需要逐项证据，系统未判断语义质量。',blocked:'只检查输出格式；代码未在隔离环境执行，不发布 pass@1。',unscorable:'没有猜测或修复不可解析的内容。',scored:'按题目公开规则离线重算。',not_applicable:'请求未完整成功，不给内容评分。'})[a.contentState])}</p>${a.checks.length?`<ul class="challenge-checks">${a.checks.map(c=>`<li><span class="${c.passed?'badge-pass':'badge-fail'}">${c.passed?'✓':'×'}</span><span>${e(c.label)} ${c.critical?'<small>核心条件</small>':''}</span><strong>${n(c.earned)} / ${n(c.points)}</strong></li>`).join('')}</ul>`:''}<details><summary>逐条输出合同（${a.constraints.filter(c=>c.passed).length}/${a.constraints.length}）</summary><ul>${a.constraints.map(c=>`<li>${c.passed?'✓':'×'} ${e(c.label)} <small>${c.required?'必要':'诊断'}</small></li>`).join('')}</ul></details>${a.review?`<div class="notice demo"><strong>${a.review.synthetic?'合成评审夹具':'本地导入的评审记录'}</strong>　评分者 ${e(a.review.reviewer)} · ${e(a.review.reviewedAt)}。系统只核对量表计算，不认证身份或语义判断。</div><ul>${a.review.items.map(x=>`<li>${e(x.id)}：${x.level}/4 · ${e(x.evidence)}</li>`).join('')}</ul>`:''}</section>`;
}

export function challengeTaskCards(tasks){return tasks.length?`<div class="task-grid challenge-task-grid">${tasks.map(t=>`<article class="task-card"><div class="chips"><span class="tag">${e(categories[t.category])}</span><span class="tag ${t.pool==='sealed'?'orange':''}">${t.pool==='sealed'?'封存':'开发'}</span></div><h3><a href="#challenge/${encodeURIComponent(t.id)}">${e(t.title)}</a></h3><p>${e(t.id)} · ${e(diff[t.difficulty])} · 未校准</p><p>${t.pool==='sealed'?'仅展示题族元数据；题面、答案和测试保留在本机私有题库。':t.grader.kind==='json'?'确定性分项评分，内容与格式分开。':t.grader.kind==='code'?'已备题面与标准；执行成绩等待隔离环境。':'已备五档人工标准；未评不填分。'}</p><a class="challenge-card-link" href="#challenge/${encodeURIComponent(t.id)}">${t.pool==='sealed'?'查看封存说明':'查看题面与评分'} →</a></article>`).join('')}</div>`:'<div class="empty"><div><strong>没有匹配的题目</strong><p>调整方向、题池或搜索词。</p></div></div>'}

function rubric(t){const g=t.grader;return `<section class="panel"><div class="panel-head"><h2>评分标准</h2><span class="tag">${e(g.version)}</span></div><div class="panel-body"><ul class="challenge-rules">${t.rubric.map(x=>`<li>${e(x)}</li>`).join('')}</ul>${g.checks.length?`<div class="table-wrap"><table class="definition-table"><thead><tr><th>能力点</th><th>分值 / 门槛</th><th>判分方式</th></tr></thead><tbody>${g.checks.map(c=>`<tr><td>${e(c.label)}</td><td>${n(c.points)} 分<small>${c.critical?'严格完成的核心条件':'诊断分项'}</small></td><td>${e({equals:'精确内容匹配',number:'数值等价及容差',set:'忽略顺序，保留重复次数'}[c.op])}<small>字段：${e(c.path.length?c.path.join('.'):'完整答案')}</small></td></tr>`).join('')}</tbody></table></div>`:''}${g.criteria.map(c=>`<details class="challenge-anchor"><summary>${e(c.label)} · ${n(c.points)} 分 · ${c.criticalLevel===null?'非核心门槛':`核心至少 ${c.criticalLevel}/4 档`}</summary><ol start="0">${c.anchors.map(x=>`<li>${e(x)}</li>`).join('')}</ol></details>`).join('')}<details><summary>查看完整评分器定义与输出约束</summary>${pre(JSON.stringify(g,null,2),'评分器完整定义')}</details><p class="evidence-meta">内容分为 0–100。严格完成按本题核心条件和必要合同判定；五档人工分是诊断量表，不是精确的能力刻度。未进行模型难度校准。</p></div></section>`}

export function createChallengeController({main,toast,download,rerender}){
 let catalog=null,report=null,error=null,loading=null,imported=false,filters={category:'all',pool:'all',query:''},scratch=new Map();
 const isPage=()=>location.hash===''||location.hash.startsWith('#challenge');
 async function load(){if(loading)return loading;loading=(async()=>{try{const response=await fetch('data/challenge.json');if(!response.ok)throw Error('题库文件 HTTP '+response.status);catalog=validateChallengeCatalog(parseChallengeJSON(await response.text()));try{const r=await fetch('data/challenge-offline.json');if(!r.ok)throw Error('离线报告 HTTP '+r.status);report=validateChallengeReport(parseChallengeJSON(await r.text()),catalog)}catch(err){error='离线证据暂不可用：'+err.message}}catch(err){error=err.message}if(isPage())rerender()})();return loading}
 function header(){return `<div class="page-head"><div><div class="eyebrow">ZHUFENG / CHALLENGE V2</div><h1>把能力差异落到具体题目</h1><p class="subtitle">查看题面、分项标准和离线验收证据。当前没有 V2 真实模型成绩。</p></div><div class="head-actions"><a class="button-link" href="#challenge/evidence">离线验收证据 ↗</a><a class="button-link" href="#challenge/protocol">评测协议 ↗</a></div></div><div class="notice"><strong>挑战题库 V2 · 开发与离线验收</strong>　新增模型 API 调用 0；题目难度和区分度尚未实测。内容分、输出合同、严格完成分别展示，旧版真实记录保留原口径。</div>`}
 function overview(){return header()+`<div class="stats">${count('候选题目',catalog.counts.total,'题族关联仍须审查，数量不证明区分度')}${count('开发题',catalog.counts.development,'公开题面与标准，可检查离线输出')}${count('封存题',catalog.counts.sealed,'本页只含元数据，不含题面或答案')}${count('V2 真实模型记录','0','离线夹具不计模型成绩')}</div><div class="core-actions"><a href="#challenge/evidence">检查正确、部分、格式及待评样例 ↗</a><a href="#overview">查看旧版数据工作台 ↗</a></div><section class="panel"><div class="panel-head"><h2>七个能力方向</h2><small>难度标签均为候选等级</small></div><div class="challenge-category-grid">${Object.entries(categories).map(([k,v])=>`<button data-challenge-category="${k}" class="${filters.category===k?'selected':''}" aria-pressed="${filters.category===k}"><span>${e(v)}</span><strong>${catalog.counts.byCategory[k]||0}</strong></button>`).join('')}</div><div class="filters"><label class="challenge-search-label">搜索题名或编号<input id="challenge-query" value="${e(filters.query)}" placeholder="例如：概率、证据、v2-m01"></label><label>方向<select id="challenge-category"><option value="all">全部方向</option>${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${filters.category===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><label>题池<select id="challenge-pool"><option value="all">全部题池</option><option value="development" ${filters.pool==='development'?'selected':''}>开发题 · 可查看全文</option><option value="sealed" ${filters.pool==='sealed'?'selected':''}>封存题 · 仅元数据</option></select></label><button data-challenge-reset>清除筛选</button></div></section><p id="challenge-count" class="count-line" aria-live="polite">${filterChallengeTasks(catalog,filters).length} 个匹配题目</p><div id="challenge-cards">${challengeTaskCards(filterChallengeTasks(catalog,filters))}</div>`}
 function task(id){const t=catalog.tasks.find(t=>t.id===id);if(!t)return '<a class="back" href="#challenge">← 返回题库</a><h1>没有找到这道题</h1>';const samples=report?.results.filter(r=>r.taskId===id)||[];return `<a class="back" href="#challenge">← 返回挑战题库</a><div class="page-head"><div><div class="eyebrow">${e(t.id)} / ${e(t.familyId)}</div><h1>${e(t.title)}</h1><p class="subtitle">${e(categories[t.category])} · ${e(diff[t.difficulty])} · 区分度待校准</p></div><span class="tag ${t.pool==='sealed'?'orange':''}">${t.pool==='sealed'?'封存池':'开发池'}</span></div>${t.pool==='sealed'?`<section class="panel"><div class="panel-body prose"><h2>题面与答案已隔离</h2><p>此页面只有题族元数据。完整题目、参考答案、评分器细节和输出保留在本机私有题库，不包含在网站数据或公开导出中。</p><p>封存不是已证明“无污染”；规则冻结后，仍需未来授权的模型测试验证区分度。</p></div></section>`:`<section class="panel"><div class="panel-head"><h2>完整题面</h2><button data-challenge-copy="${e(t.id)}">复制题面</button></div><div class="panel-body">${pre(t.prompt,'完整题面')}${t.messages?`<details><summary>固定对话上下文（不是实时多轮 Agent 测试）</summary>${t.messages.map(m=>`<p><strong>${e(m.role)}</strong></p>${pre(m.content,'对话消息')}`).join('')}</details>`:''}${(t.assets||[]).map(a=>`<details><summary>给定文件：${e(a.path)}</summary>${pre(a.content,a.path)}</details>`).join('')}<details><summary>展开参考答案与判分依据</summary>${pre(t.reference,'参考答案')}</details></div></section>${rubric(t)}<section class="panel"><div class="panel-head"><h2>本地试判</h2><small>不调用 API，不上传回答</small></div><div class="panel-body"><label for="challenge-answer">粘贴一份回答，检查规则如何计分</label><textarea id="challenge-answer" rows="8" spellcheck="false" data-task="${e(t.id)}">${e(scratch.get(t.id)?.output||'')}</textarea><button data-challenge-assess="${e(t.id)}" class="primary">离线试判这份回答</button><div id="challenge-scratch-result" aria-live="polite">${scratch.get(t.id)?challengeAssessment(scratch.get(t.id).assessment):''}</div><p class="evidence-meta">代码不会执行，SVG 仅检查静态格式并以源码显示；人工内容保持待评。本地试判不是模型实测。</p></div></section><section class="panel"><div class="panel-head"><h2>${report?.dataKind==='imported'?'这道题的本地答卷':'这道题的离线样例'}</h2><span class="tag">${report?.dataKind==='imported'?'来源未认证':'DEMO'} · ${samples.length} 条</span></div><div class="panel-body">${samples.length?samples.map(sample).join(''):'<p>暂无可公开核对的夹具报告。</p>'}</div></section>`}<section class="panel"><div class="panel-body prose"><h2>来源与核验边界</h2><p>${link(t.source.url,t.source.name)} · ${e(t.source.note)}</p><p>${e(t.verification.method)}：${e(t.verification.notes)}</p><p>独立交叉检查：${t.verification.independentCheck?'已记录（不代表模型实测）':'未声明完成'}。${t.pool==='sealed'?'公开信息经过概括，不能据此复原私有题目。':''}</p></div></section>`}
 function sample(r){if(report?.dataKind==='imported')return `<details class="challenge-fixture"><summary>${e(r.id)} · 本地答卷 <span class="tag orange">来源未认证</span></summary>${challengeAssessment(r.assessment)}<details><summary>原始回答</summary>${pre(r.output,'本地回答')}</details></details>`;return `<details class="challenge-fixture"><summary>${e(r.fixtureName)} · ${r.passed?'符合夹具预期':'与预期不符'} <span class="tag">合成回答</span></summary>${challengeAssessment(r.assessment)}<details><summary>原始预设输出</summary>${pre(r.output,'预设输出')}</details><details><summary>夹具预期与实际结果</summary>${pre(JSON.stringify({expected:r.expected,actual:{contentScore:r.assessment.contentScore,formatPassed:r.assessment.formatPassed,strictPassed:r.assessment.strictPassed,contentState:r.assessment.contentState}},null,2),'夹具核对')}</details></details>`}
 function evidence(){const results=report?.results||[];return `<a class="back" href="#challenge">← 返回题库</a><div class="page-head"><div><div class="eyebrow">LOCAL ACCEPTANCE / DEMO</div><h1>${report?.dataKind==='imported'?'本地答卷评阅':'离线验收证据'}</h1><p class="subtitle">正确、部分正确、格式违规和待评输出，检查评分器是否遵守自己的规则。</p></div>${report?'<button data-challenge-export>导出公开报告 ↓</button>':''}</div><div class="notice demo"><strong>${imported?'本地导入 · 未独立认证':'本机合成夹具 · 非模型成绩'}</strong>　公开回答的自动内容分与合同均在浏览器重算；人工评审只校验量表计算，不认证判断。此页没有模型排行榜。</div>${error?`<p class="notice">${e(error)}</p>`:''}<div class="stats">${count(report?.dataKind==='imported'?'本地答卷':'公开夹具',results.length,'仅开发池，排除封存输出')}${count(report?.dataKind==='imported'?'严格完成':'符合夹具预期',results.filter(x=>report?.dataKind==='imported'?x.assessment.strictPassed===true:x.passed).length,report?.dataKind==='imported'?'按当前公开规则重算，来源未认证':'格式失败也可能是预期结果')}${count('人工待评',results.filter(x=>x.assessment.contentState==='pending').length,'不补零，不补为通过')}${count('代码待执行',results.filter(x=>x.assessment.contentState==='blocked').length,'不发布 pass@1')}</div><section class="upload"><label for="challenge-import"><strong>导入 V2 公开报告或本地答卷</strong></label><input type="file" accept=".json,application/json" id="challenge-import"><p>仅当前标签页处理；接受本题库开发题的离线报告或 CLI 导出的本地答卷。导入答卷不冒充本站实测，字段、任务引用和评分重新检查，封存回答会被拒绝。</p>${imported?'<button data-challenge-restore>恢复随站报告</button>':''}</section>${report?.summary?`<details><summary>构建器报告的汇总计数</summary>${pre(JSON.stringify(report.summary,null,2),'构建汇总')}<p class="evidence-meta">浏览器能重算公开夹具；封存汇总来自本地构建器，不在网页中独立复验。导入文件的汇总来源未经认证。</p></details>`:''}<section class="panel"><div class="panel-body">${results.length?catalog.tasks.filter(t=>results.some(r=>r.taskId===t.id)).map(t=>`<details><summary>${e(t.id)} · ${e(t.title)} · ${results.filter(r=>r.taskId===t.id).length} 条样例</summary><a class="source" href="#challenge/${e(t.id)}">对照题目与评分标准 ↗</a>${results.filter(r=>r.taskId===t.id).map(sample).join('')}</details>`).join(''):'<p>离线报告尚不可用，不能据此声称验收通过。</p>'}</div></section>`}
 function protocol(){return `<a class="back" href="#challenge">← 返回题库</a><div class="page-head"><div><div class="eyebrow">CHALLENGE V2 / PROTOCOL</div><h1>规则先固定，成绩再产生</h1><p class="subtitle">自编挑战题库，借鉴成熟评测方法；未复现官方 benchmark 分数。</p></div></div><section class="panel"><div class="panel-body prose"><h2>三层成绩</h2><ol><li><strong>内容完成度：</strong>按可检查能力点计 0–100 分，保留部分分。</li><li><strong>输出合同：</strong>格式、字段和明确约束逐条核验。解开一层 JSON 围栏可诊断内容，原文格式仍失败。</li><li><strong>严格完成：</strong>核心条件和必要合同都满足才通过。人工待评、代码待隔离执行均为待定。</li></ol><h2>当前执行范围</h2><p>Windows 与现有 Python/Node 流程；新增模型 API 预算为 0。网站展示开发题、公开标准和合成验收报告。模型生成代码不在宿主机执行；SVG 输出也不作为活动网页直接插入。</p><h2>开发池与封存池</h2><p>开发池用于校准和检查评分器。封存题仅有元数据进入网站；题面、答案、生成材料及测试保留在评测机私有目录。看过封存结果后调题或调权，需要将该题转入开发池并使用新的留出题。</p><h2>人工评分</h2><p>每项有五档具体锚点，必须记录扣分证据和评分时间。系统不认证评审身份，不把单人评分称为独立双评，不把合成评审夹具称为真人复核。</p><h2>未完成的实证环节</h2><p>离线验收只能证明评分规则在已覆盖样例上的行为。题目难度、强模型区分度、重测稳定性和排名都需要以后另行授权的真实测试。72 个候选题目也不自动代表 72 个相互独立的能力证据。</p><h2>速度与成本单独看</h2><p>TPS、首正文延迟和费用不与这套内容分混合。历史真实采集保留旧协议；这套 V2 没有新增真实记录、可核实费用或模型速度成绩。</p><div class="head-actions"><a href="#challenge/evidence">离线报告 ↗</a><a href="#workflow">原运行器流程 ↗</a><a href="#speed">历史速度与稳定性 ↗</a></div></div></section>`}
 function render(id=''){if(!catalog){load();return `<div class="page-head"><div><h1>挑战题库 V2</h1><p class="subtitle">${error?e(error):'正在读取本地题库与离线证据…'}</p></div></div>`}return id==='evidence'?evidence():id==='protocol'?protocol():id?task(decodeURIComponent(id)):overview()}
 main.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.challengeCategory){filters.category=b.dataset.challengeCategory;rerender()}if(own(b.dataset,'challengeReset')){filters={category:'all',pool:'all',query:''};rerender()}if(b.dataset.challengeCopy){const t=catalog.tasks.find(t=>t.id===b.dataset.challengeCopy);await navigator.clipboard.writeText(t.prompt);toast('已复制开发题题面')}if(b.dataset.challengeAssess){const t=catalog.tasks.find(t=>t.id===b.dataset.challengeAssess),output=document.querySelector('#challenge-answer').value,assessment=replayChallenge(output,t.grader,t.id);scratch.set(t.id,{output,assessment});document.querySelector('#challenge-scratch-result').innerHTML=challengeAssessment(assessment)}if(own(b.dataset,'challengeExport')&&report)download(JSON.stringify(report,null,2),report.dataKind==='imported'?'zhufeng-challenge-v2-local-responses.json':'zhufeng-challenge-v2-offline-demo.json','application/json');if(own(b.dataset,'challengeRestore')){report=null;catalog=null;error=null;loading=null;imported=false;rerender()}}catch(err){toast('操作未完成：'+err.message)}});
 main.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='challenge-category'||el.id==='challenge-pool'){filters[el.id==='challenge-category'?'category':'pool']=el.value;rerender()}if(el.id==='challenge-import'){try{const file=el.files?.[0];if(!file)return;if(file.size>15*1024*1024)throw Error('报告超过 15 MB');const input=parseChallengeJSON(await file.text());report=input.schemaVersion==='challenge-results-v2'?validateChallengeResponses(input,catalog):validateChallengeReport(input,catalog);imported=true;error=null;rerender();toast('已导入并重算公开结果；文件未上传')}catch(err){toast('导入失败：'+err.message);el.value=''}}});
 main.addEventListener('input',ev=>{if(ev.target.id==='challenge-query'){filters.query=ev.target.value;const tasks=filterChallengeTasks(catalog,filters);document.querySelector('#challenge-cards').innerHTML=challengeTaskCards(tasks);document.querySelector('#challenge-count').textContent=tasks.length+' 个匹配题目'}});
 return {render};
}
